insert into public.students (id, name, roll_no, email, branch, batch_year, current_semester, cgpa, skills, interests, dream_companies, bio, avatar_url, github_url, linkedin_url) values
  ('student-aarav-sharma', 'Aarav Sharma', '04214803122', 'aarav.sharma.cst22@mait.ac.in', 'Computer Science & Technology (CST)', '2022 - 2026', 6, 8.84, '["TypeScript","React","Node.js","Distributed Systems","C++","PostgreSQL","Docker"]'::jsonb, '["Cloud Architecture","High-Scale Backend","Open Source","Competitive Programming"]'::jsonb, '["Google","Microsoft","Blinkit","Amazon","Sprinklr"]'::jsonb, 'MAIT CST 3rd year student passionate about building scalable microservices and distributed databases. Active member of MAIT IOSD and ACM student chapters.', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=400&q=80', 'https://github.com/aarav-mait-cst', 'https://linkedin.com/in/aarav-sharma-cst')
insert into public.alumni (id, name, email, branch, grad_year, current_company, designation, location, skills, bio, avatar_url, linkedin_url, github_url, is_available_for_mentoring, total_mentored, specialties, verified_by_mait) values
  ('alumni-priya-goel', 'Priya Goel', 'priya.goel@alumni.mait.ac.in', 'Computer Science & Technology (CST)', 2019, 'Google', 'Senior Software Engineer (L5)', 'Bengaluru, India', '["Golang","Kubernetes","Cloud Infrastructure","Distributed Systems","gRPC","System Design"]'::jsonb, 'MAIT CST 2019 batch. Currently designing reliable multi-region telemetry at Google Cloud. Former SDE at Amazon AWS. Love helping juniors crack tier-1 product engineering loops.', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=400&q=80', 'https://linkedin.com/in/priya-goel-google', 'https://github.com/priyagoel-cloud', true, 28, '["System Design & Distributed Systems","Off-Campus Referral Strategy","DSA & Technical Mock Interview"]'::jsonb, true),
  ('alumni-rohan-verma', 'Rohan Verma', 'rohan.verma@alumni.mait.ac.in', 'Computer Science & Technology (CST)', 2021, 'Blinkit (Zomato Group)', 'Staff Backend Architect', 'Gurugram, India', '["Java","Spring Boot","Kafka","Redis","Event-Driven Systems","PostgreSQL","High Concurrency"]'::jsonb, 'CST 2021 grad. Architected 10-minute order dispatch queues and real-time inventory locking at Blinkit. Founded MAIT TechFest Hackathon in final year.', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&q=80', 'https://linkedin.com/in/rohan-verma-blinkit', 'https://github.com/rohan-blinkit-tech', true, 19, '["Resume & Portfolio Review","Early-Stage Startup & Tech Lead","System Design & Distributed Systems"]'::jsonb, true),
  ('alumni-ananya-singhal', 'Ananya Singhal', 'ananya.s@alumni.mait.ac.in', 'Computer Science & Technology (CST)', 2018, 'Microsoft', 'Principal Applied Scientist (AI)', 'Hyderabad, India', '["PyTorch","LLMs","Transformer Architectures","RAG","Python","Azure AI","Generative AI"]'::jsonb, 'MAIT CST 2018 gold medalist. MS in CS from Georgia Tech. Now researching small language models and enterprise grounding at Microsoft AI Hyderabad.', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=400&q=80', 'https://linkedin.com/in/ananya-singhal-msft', 'https://github.com/ananya-ai-research', true, 34, '["Higher Studies & MS Abroad","DSA & Technical Mock Interview","Resume & Portfolio Review"]'::jsonb, true),
  ('alumni-kabir-malhotra', 'Kabir Malhotra', 'kabir.m@alumni.mait.ac.in', 'Computer Science & Technology (CST)', 2020, 'Amazon', 'SDE-II (AWS FinTech)', 'Delhi NCR, India', '["AWS ECS","Java","DynamoDB","Microservices","Clean Code","Terraform"]'::jsonb, 'MAIT CST 2020. Working on high-volume real-time ledger settlement engines at AWS. Regular speaker at Delhi Java User Group.', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&q=80', 'https://linkedin.com/in/kabir-malhotra-aws', 'https://github.com/kabir-aws', false, 14, '["Off-Campus Referral Strategy","DSA & Technical Mock Interview"]'::jsonb, true),
  ('alumni-simran-bhatia', 'Simran Bhatia', 'simran.b@alumni.mait.ac.in', 'Computer Science & Technology (CST)', 2017, 'Adobe', 'Engineering Manager (Experience Cloud)', 'Noida, India', '["Engineering Leadership","React","C++","WebGL","Agile Architecture","Cross-Functional Strategy"]'::jsonb, 'MAIT CST 2017 alumni. Leading a team of 14 software engineers at Adobe India building generative canvas tools for enterprise creators.', 'https://images.unsplash.com/photo-1534751516642-a171ed292728?auto=format&fit=crop&w=400&q=80', 'https://linkedin.com/in/simran-bhatia-adobe', 'https://github.com/simran-adobe', true, 42, '["Resume & Portfolio Review","Early-Stage Startup & Tech Lead"]'::jsonb, true),
  ('alumni-divyansh-gupta', 'Divyansh Gupta', 'divyansh.g@alumni.mait.ac.in', 'Computer Science & Technology (CST)', 2022, 'Goldman Sachs', 'Quantitative Developer & SDE', 'Bengaluru, India', '["C++","Low Latency","Algorithmic Trading","Linux Kernel","Network Sockets","Python"]'::jsonb, 'MAIT CST 2022. Secured GS on-campus offer through competitive programming (Codeforces Master 2180). Eager to coach students on tough DSA and OS internals.', 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?auto=format&fit=crop&w=400&q=80', 'https://linkedin.com/in/divyansh-gupta-quant', 'https://github.com/divyansh-quant', true, 16, '["DSA & Technical Mock Interview","System Design & Distributed Systems"]'::jsonb, true),
  ('alumni-tanvi-aggarwal', 'Tanvi Aggarwal', 'tanvi.a@alumni.mait.ac.in', 'Computer Science & Technology (CST)', 2023, 'Sprinklr', 'Product Engineer', 'Gurugram, India', '["Next.js","TypeScript","Node.js","ElasticSearch","GraphQL","Tailwind CSS"]'::jsonb, 'MAIT CST 2023 batch. Placed during 7th semester campus drives. Loves building responsive frontend ecosystems and AI conversational widgets.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400&q=80', 'https://linkedin.com/in/tanvi-aggarwal-sprinklr', 'https://github.com/tanvi-dev', true, 9, '["Resume & Portfolio Review","Off-Campus Referral Strategy"]'::jsonb, true),
  ('alumni-ayush-mathur', 'Ayush Mathur', 'ayush.m@alumni.mait.ac.in', 'Computer Science & Technology (CST)', 2016, 'AgrasenTech (YC W22)', 'Co-Founder & CTO', 'Bengaluru / San Francisco', '["Product Strategy","Venture Capital","Rust","Cloud Native","Go","Zero-to-One"]'::jsonb, 'MAIT CST 2016. Y Combinator alumni. Scaled from 2 guys in MAIT hostel to 80+ employees and $12M Series A. Helping students who want to build startups.', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=400&q=80', 'https://linkedin.com/in/ayush-mathur-founder', 'https://github.com/ayush-yc', true, 21, '["Early-Stage Startup & Tech Lead","Off-Campus Referral Strategy"]'::jsonb, true)
insert into public.opportunities (id, title, type, company_or_organizer, location, mode, description, requirements, skills, deadline_or_date, posted_by_role, poster_id, poster_name, poster_company, poster_grad_year, status, registered_student_ids, compensation_or_fee, link_url, created_at, is_referral_by_alumni) values
  ('opp-google-sde1-2026', 'Google SDE-1 (Early Career Referral Pool)', 'job', 'Google', 'Bengaluru / Hyderabad', 'Hybrid', 'Direct referral opportunity for MAIT CST 2025/2026 graduates. Roles across Google Cloud, Android Core, and Ads Platform teams. Alumni will review profiles before submitting to internal Google referral portal.', '["Strong command of Data Structures & Algorithms","Proficiency in Java, C++, Go, or Python","Solid foundations in OS, Computer Networks, and DBMS","Minimum CGPA 7.5"]'::jsonb, '["DSA","System Design","C++","Java","Distributed Systems"]'::jsonb, '2026-05-30', 'alumni', 'alumni-priya-goel', 'Priya Goel', 'Google', 2019, 'approved', '["student-aarav-sharma"]'::jsonb, '₹28 - ₹34 LPA + RSUs', 'https://careers.google.com', '2026-11-01T10:00:00Z', true),
  ('opp-blinkit-backend-intern', 'Summer 2026 Backend Systems Intern', 'internship', 'Blinkit (Zomato Group)', 'Gurugram, Haryana', 'Hybrid', 'Work directly on high-throughput microservices handling 250k concurrent orders per minute. You will write high-performance Kafka streams and Redis distributed caches.', '["Pre-final year CST/IT students (Graduating 2027)","Hands-on experience with Node.js/Go/Java","Understanding of ACID transactions and concurrency issues"]'::jsonb, '["Node.js","Go","Kafka","Redis","PostgreSQL"]'::jsonb, '2026-04-15', 'alumni', 'alumni-rohan-verma', 'Rohan Verma', 'Blinkit', 2021, 'approved', '[]'::jsonb, '₹75,000 / month Stipend + PPO', 'https://blinkit.com/careers', '2026-11-02T14:30:00Z', true),
  ('opp-webinar-system-design', 'Masterclass: Cracking FAANG Off-Campus Referrals from MAIT', 'webinar', 'MAIT CST Alumni Circle', 'Online via Google Meet', 'Remote', 'Join Priya Goel (Google), Divyansh Gupta (Goldman Sachs), and Rohan Verma (Blinkit) as they break down the exact strategies used by MAIT students to secure top offers without on-campus tier-1 visits.', '["Open to all MAIT CST students (1st through 4th year)","Bring your questions and your current resume"]'::jsonb, '["Interview Prep","Resume Building","Cold Emailing","System Design"]'::jsonb, '2026-11-20', 'admin', 'admin-mait-cst', 'Prof. Dr. S.K. Mittal', 'MAIT CST Dept', null, 'approved', '["student-aarav-sharma"]'::jsonb, 'Free for MAITians', 'https://meet.google.com/mait-cst-talk', '2026-11-03T09:15:00Z', null),
  ('opp-reunion-dec2026', 'MAIT CST Grand Silver Alumni Reunion 2026', 'reunion', 'Maharaja Agrasen Institute of Technology', 'MAIT Main Auditorium, Block 1, Rohini Sector 22, Delhi', 'On-site', 'Annual gathering of MAIT Computer Science & Technology alumni across batches 2005 - 2025. Connect with batchmates, tour new AI & Robotics labs, and network with faculty & current student innovators.', '["All MAIT alumni, faculty, and student council members welcome","Dinner and networking cocktail provided"]'::jsonb, '["Alumni Networking","Mentorship","Institutional Growth"]'::jsonb, '2026-12-19', 'admin', 'admin-mait-cst', 'Prof. Dr. S.K. Mittal', 'MAIT CST Dept', null, 'approved', '[]'::jsonb, 'Pass: ₹500 (Free for Student Volunteers)', 'https://mait.ac.in/alumni-reunion', '2026-10-25T11:00:00Z', null),
  ('opp-pending-sprinklr-role', 'Sprinklr Associate Product Engineer 2026', 'job', 'Sprinklr', 'Gurugram, India', 'On-site', 'Seeking passionate product engineers to work on conversational AI interfaces and large-scale enterprise social intelligence suites.', '["Final year B.Tech CST/IT","Strong React, TypeScript, and Data Structures background"]'::jsonb, '["React","TypeScript","DSA","REST APIs"]'::jsonb, '2026-06-15', 'alumni', 'alumni-tanvi-aggarwal', 'Tanvi Aggarwal', 'Sprinklr', 2023, 'pending', '[]'::jsonb, '₹18 - ₹22 LPA CTC', null, '2026-11-04T08:00:00Z', true),
  ('opp-pending-ai-summit', 'MAIT AI & ML Research Hackathon 2026', 'webinar', 'MAIT Student ACM Chapter & Alumni Mentors', 'MAIT Lab 304 & Discord', 'Hybrid', '36-hour hackathon challenging students to build with Gemini and open-source models for healthcare and urban mobility in Delhi NCR.', '["Teams of 2-4 students","At least one CST/CSE student per team"]'::jsonb, '["GenAI","Python","FastAPI","React"]'::jsonb, '2026-12-05', 'alumni', 'alumni-ananya-singhal', 'Ananya Singhal', 'Microsoft', 2018, 'pending', '[]'::jsonb, '₹1,50,000 Total Prize Pool', null, '2026-11-04T12:00:00Z', null)
insert into public.mentorship_requests (id, student_id, student_name, student_branch, student_semester, student_cgpa, alumni_id, alumni_name, alumni_company, alumni_designation, topic, message, preferred_mode, status, requested_at, response_note, meeting_url) values
  ('req-1', 'student-aarav-sharma', 'Aarav Sharma', 'CST 3rd Year (Sem 6)', 6, 8.84, 'alumni-priya-goel', 'Priya Goel', 'Google', 'Senior Software Engineer (L5)', 'System Design & Distributed Systems', 'Hello Priya Maam, I am in 6th semester CST at MAIT. I have built a distributed message queue in Go and solved 350+ LeetCode problems. Would love guidance on structuring my resume for Google Cloud referrals.', 'Google Meet', 'accepted', '2026-11-02T16:20:00Z', 'Great initiative Aarav! Your Go project sounds very relevant to what my team does. Let us catch up on Saturday 4 PM.', 'https://meet.google.com/mait-priya-aarav'),
  ('req-2', 'student-aarav-sharma', 'Aarav Sharma', 'CST 3rd Year (Sem 6)', 6, 8.84, 'alumni-rohan-verma', 'Rohan Verma', 'Blinkit', 'Staff Backend Architect', 'Resume & Portfolio Review', 'Hi Rohan Sir, I am preparing for 2026 Summer Backend internships and saw your post on high-concurrency dispatch systems at Blinkit. Could you review my portfolio and give tips for the technical interview?', 'LinkedIn Voice/Chat', 'pending', '2026-11-04T09:10:00Z', null, null),
  ('req-3', 'student-isha-kapoor', 'Isha Kapoor', 'CST 4th Year (Sem 8)', 8, 9.12, 'alumni-ananya-singhal', 'Ananya Singhal', 'Microsoft', 'Principal Applied Scientist (AI)', 'Higher Studies & MS Abroad', 'Respected Ananya Maam, I have published a paper on Transformer attention mechanisms and am applying for MS CS Fall 2027 in the US. Seeking your advice on SOP and selecting labs.', 'Google Meet', 'pending', '2026-11-04T11:45:00Z', null, null)
